'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const nf=v=>Number.isFinite(v)?Math.round(v).toLocaleString('ko-KR'):'미확인';
const storage={get(k,f){try{return window.AtlasCloud?.get('atlas2-'+k,f)??f;}catch{return f;}},set(k,v){try{return window.AtlasCloud?.set('atlas2-'+k,v)===true;}catch{return false;}}};
const icons={opening:'<path d="M5 3h14v18H5z M9 7h6 M9 11h6 M9 15h2 M14 15l1 1 3-3"/>',discover:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',area:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Z M9 3v16m6-14v16"/>',places:'<path d="M4 10h16v11H4V10Zm-1 0 2-7h14l2 7M9 21v-7h6v7M3 10c1 3 4 3 5 0 1 3 4 3 5 0 1 3 4 3 5 0"/>',rivals:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v3"/>',saved:'<path d="M5 3h14v18l-7-4-7 4Z"/>'};
const navItems=[['opening','갈매기살 개점 계획','개점'],['discover','업종 찾기','추천'],['area','동네 분석','상권'],['places','매물 & 손익','매물'],['rivals','경쟁점 조사','경쟁'],['saved','내 출점 검토','내 검토']];
const svgIcon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]}</svg>`;
const labels={daypart:{lunch:'점심·낮',evening:'저녁 중심',allday:'하루 종일'},experience:{new:'처음 창업',experienced:'운영 경험 있음'},service:{any:'아직 모름',quick:'식사·포장',cafe:'카페',dining:'주점·다이닝'}};
let DATA,COMPETITION={areas:[]},RIVALS={rivals:[]},recommendation=null,map=null,mapGeneration=0,toastTimer,financeResult=null;
let state={country:storage.get('country','KR'),area:null,view:'discover',age:'20-39',population:'flow',category:'all',profile:null,finance:null,property:null,propertyRecord:null,concept:null};
const C=()=>DATA.countries[state.country],A=()=>C().areas.find(a=>a.id===state.area)||C().areas[0];
const ca=()=>state.country==='KR'?COMPETITION.areas.find(a=>a.id===state.area):null;
const money=(v,country=state.country)=>Number.isFinite(v)?(country==='KR'?'₩':'¥')+Math.round(v).toLocaleString('ko-KR'):'미확인';
const shortMoney=(v,country=state.country)=>{if(!Number.isFinite(v))return '미확인';return (v/10000).toLocaleString('ko-KR',{maximumFractionDigits:1})+(country==='KR'?'만원':'만 엔');};
const ageLabel=k=>k==='first'?(pop()?.sourceAgeLabel||A()?.sourceAgeLabel||(state.country==='KR'?'연령구간 10 (원자료)':'0–19세')):({'20-39':'20–39세','40-59':'40–59세','60+':'60세 이상',all:'전체 연령'}[k]||k);
const pop=()=>state.population==='flow'?A()?.flow:A()?.residents;
const share=(a,k=state.age)=>{const d=state.population==='flow'?a.flow:a.residents;return d?.total>0?(k==='all'?100:(Number.isFinite(d.groups?.[k])?d.groups[k]/d.total*100:null)):null;};
const safeUrl=v=>{try{const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:null;}catch{return null;}};
const link=(url,label,cls='')=>safeUrl(url)?`<a class="${cls}" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:`<span>${esc(label)} · 링크 없음</span>`;
const list=(a,cls='')=>`<ul class="${cls}">${(a||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
const newProfile=()=>({totalBudget:null,daypart:'lunch',experience:'new',service:'any'});
const defaults={KR:{rent:1800000,management:100000,payroll:5500000,otherFixed:900000,depreciation:300000,variableRate:.38,ticket:12000,days:26,seats:20,turns:3,occupancy:.65,ordersPerDay:80,capacityBasis:'seats',debtPrincipal:0,targetProfit:2000000,deposit:30000000,transfer:0,fitout:25000000,openingCosts:3000000,reserve:15000000},JP:{rent:300000,management:20000,payroll:650000,otherFixed:150000,depreciation:50000,variableRate:.36,ticket:1300,days:26,seats:20,turns:3,occupancy:.65,ordersPerDay:80,capacityBasis:'seats',debtPrincipal:0,targetProfit:250000,deposit:1800000,transfer:0,fitout:2500000,openingCosts:400000,reserve:1500000}};
const checks=[['lunch','평일 11–14시 현장 보기','직장인 이동, 구내식당, 경쟁점 대기·회전 기록'],['evening','평일 저녁·주말 수요 보기','평일 점심과 다른 방문 목적과 주말 공백 확인'],['menu','경쟁점 3곳 메뉴·객단가 확인','같은 고객·같은 가격대의 식사 대안 포함'],['building','음식점 운영 조건 확인','건축물 용도, 배기·급배수·전기·영업시간'],['quote','실제 비용 견적 받기','부가세, 관리비, 권리금, 공사비·예비자금']];

function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function persist(k,v){const ok=storage.set(k,v);if(!ok)toast('기록을 저장하지 못했습니다. 연결·동기화 설정에서 상태를 확인해 주세요.');return ok;}
function loadCountry(){const c=C(),desired=storage.get('area-'+state.country,null),snapshots=[storage.get('area-snapshot-'+state.country,null),storage.get('area-record-'+state.country,null)].filter(a=>validAreaSnapshot(a,state.country)),cached=snapshots.find(a=>String(a.id)===String(desired))||(!desired?snapshots[0]:null);if(cached){const area=normalizeArea(cached),i=c.areas.findIndex(a=>a.id===area.id);if(i<0)c.areas.push(area);else if(c.areas[i].isRestoring)c.areas[i]=area;}state.area=desired?String(desired):(cached?String(cached.id):c.areas[0]?.id);if(!c.areas.some(a=>a.id===state.area)){c.areas.push(normalizeArea({id:state.area,name:'저장한 지역 불러오는 중',country:state.country,isRestoring:true}));}state.restoreAreaId=c.areas.find(a=>a.id===state.area)?.isRestoring?state.area:null;state.profile=storage.get('profile-'+state.country,newProfile());state.finance=storage.get('finance-'+state.country,{...defaults[state.country]});state.concept=storage.get('concept-'+state.country,null);state.property=storage.get('property-'+state.country,null);state.propertyRecord=storage.get('property-record-'+state.country,null);state.population=A()?.flow?'flow':'residents';state.category='all';$('#country-select').value=state.country;calculateRecommendations();}
function calculateRecommendations(){recommendation=state.profile.totalBudget?AtlasRecommend.recommend({country:state.country,area:A(),profile:state.profile,competition:ca()}):null;}
function renderNav(){for(const [id,desktop]of [['desktop-nav',true],['mobile-nav',false]])$('#'+id).innerHTML=navItems.map(([k,title,mobile])=>`<button data-nav="${k}" class="${state.view===k?'active':''}" ${state.view===k?'aria-current="page"':''}>${svgIcon(k)}<span>${desktop?title:mobile}</span></button>`).join('');$('#breadcrumb').textContent='출점 리서치 / '+navItems.find(x=>x[0]===state.view)[1];}
function navigate(view,scroll=true){if(!navItems.some(x=>x[0]===view))view='discover';state.view=view;if(location.hash!=='#'+view)history.replaceState(null,'','#'+view);render();if(scroll)window.scrollTo({top:0,behavior:'instant'});}
function chooseArea(id){if(!C().areas.some(a=>a.id===id))return;state.area=id;state.restoreAreaId=null;persist('area-'+state.country,id);persist('area-snapshot-'+state.country,A());if(!A().flow)state.population='residents';calculateRecommendations();render();window.AtlasBeta?.loadCompetition();}
function regionPicker(){return `<div class="region-picker"><button type="button" id="region-search" class="region-search-button" data-beta="region-search" aria-haspopup="dialog"><span><small>${esc(A().province||A().district||C().label)}</small><strong>${esc(A().name)}</strong></span><span aria-hidden="true">⌕</span></button></div>`;}
function intro(k,title,desc){return `<div class="page-intro"><div class="eyebrow">${k}</div><h1>${title}</h1><p>${desc}</p></div>`;}
function stats(){const a=A(),d=Number.isFinite(a.flow?.total)?a.flow:a.residents,young=d?.groups?.['20-39'],ratio=Number.isFinite(young)&&d?.total>0?(young/d.total*100).toFixed(1):null,coffee=ca()?.industries?.find(i=>i.key==='cafe');return `<div class="mini-stats"><div class="mini-stat highlight"><label>20–39세 ${d===a.flow?'생활인구':'거주인구'} 비중</label><strong>${ratio===null?'미확인':ratio}<small>${ratio===null?'':'%'}</small></strong><p>${esc(d?.date||'자료 미연결')} · ${d===a.flow?'통신 기반 추정':'지역 집계'}</p></div><div class="mini-stat"><label>${state.country==='KR'?'직장인구 추정':'민간 사업장 종사자'}</label><strong>${nf(a.workers?.total)}<small>${Number.isFinite(a.workers?.total)?'명':''}</small></strong><p>${esc(a.workers?.date||'자료 미연결')}</p></div><div class="mini-stat"><label>전체 거주인구</label><strong>${nf(a.residents?.total)}<small>${Number.isFinite(a.residents?.total)?'명':''}</small></strong><p>${esc(a.residents?.date||'자료 미연결')}</p></div><div class="mini-stat"><label>${state.country==='KR'?'커피·음료 분기 집계 점포':'음식점 사업소'}</label><strong>${nf(state.country==='KR'?coffee?.reported_store_count:a.workers?.food)}<small>개</small></strong><p>${state.country==='KR'?(coffee?'2026년 2분기 · 현재 영업수 아님':'업종별 집계 미연결'):'2021년 경제센서스 · 현재 수 아님'}</p></div></div>`;}
function updateProfileSummary(){const el=$('.extra-profile summary span');if(el)el.textContent=labels.experience[state.profile.experience]+' · '+labels.service[state.profile.service];}
function chips(key,values,value){return `<div class="chip-group">${Object.entries(values).map(([v,label])=>`<button type="button" class="chip ${value===v?'active':''}" data-profile-key="${key}" data-profile-value="${v}" aria-pressed="${value===v}">${esc(label)}</button>`).join('')}</div>`;}
function renderDiscover(){const p=state.profile;return intro('START WITH YOUR CONDITIONS','내 조건에 맞는<br class="mobile-only"> 가게를 찾아보세요.','막막한 창업 준비, 지역과 예산부터.<br>업종 후보를 고르고 실제 매물 비용으로 확인하세요.')+`<div class="discovery-layout"><form class="card fit-form" id="fit-form"><h2><span class="step-dot">1</span>어디서, 어떻게 시작할까요?</h2><div class="form-grid"><div class="full"><label class="form-label" for="region-search">관심 동네</label>${regionPicker()}</div><div class="full"><label class="form-label" for="budget-input">총 창업 예산 · 보증금과 예비자금 포함</label><div class="input-wrap"><input id="budget-input" name="budget" type="number" inputmode="decimal" min="1" max="10000000" step="1" placeholder="${state.country==='KR'?'예: 8,000':'예: 800'}" value="${p.totalBudget?p.totalBudget/10000:''}" required><span class="input-unit">${state.country==='KR'?'만원':'만 엔'}</span></div><span class="field-note">실제로 조달할 수 있는 총액을 입력해 주세요.</span></div><div class="full"><span class="form-label">운영 가능한 시간</span>${chips('daypart',labels.daypart,p.daypart)}</div><details class="full extra-profile"><summary>경험·관심 업종 <span>${esc(labels.experience[p.experience])} · ${esc(labels.service[p.service])}</span></summary><div><span class="form-label">음식점 운영 경험</span>${chips('experience',labels.experience,p.experience)}</div><div style="margin-top:15px"><label class="form-label" for="service-select">생각 중인 운영 형태</label><select id="service-select">${Object.entries(labels.service).map(([v,s])=>`<option value="${v}" ${p.service===v?'selected':''}>${s}</option>`).join('')}</select></div></details></div><button type="submit" class="button wide">이 조건으로 업종 찾기 <span>→</span></button><div id="fit-error" class="form-error" role="status"></div><p class="form-caption">예산·운영 조건과 공개 지역 자료를 이용한 검토 순위입니다. 실제 수요를 확인한 성공 예측은 아닙니다.</p></form><section class="section"><div class="section-head"><h2>${esc(A().name)} 먼저 보기</h2><button class="text-button" data-nav="area">상세 분석 →</button></div>${stats()}<p class="intro-tip">${state.country==='KR'?'상권에 사람이 많아도 내 가게의 고객은 다릅니다. 점심·저녁 동선과 같은 가격대 경쟁점을 함께 확인해 보세요.':'거주 인구와 직장 종사자는 방문객이 아닙니다. 2021년 사업장 자료는 현재 직장 수요의 참고자료입니다.'}</p><div class="status-line"><span class="live-dot"></span>${esc(C().scope)} · 기준일별 자료 · 연결 상태 별도 확인</div><div class="button-row"><button class="button secondary small" data-nav="rivals">주변 경쟁점 보기</button><button class="button secondary small" data-nav="places">상가 비용 살펴보기</button></div></section></div><section id="recommend-results">${recommendation?renderRecommendations():`<div class="section empty-state"><span class="empty-symbol">✳</span><h3>내 예산에 맞는 업종부터 좁혀보세요.</h3><p>예산과 운영 조건을 입력하면 최대 3개 후보와<br>손익분기에 필요한 하루 판매량을 보여드립니다.</p></div>`}</section>`;}
function renderRecommendations(){const r=recommendation;if(!r.valid)return `<div class="notice red">${esc(r.errors.join(' '))}</div>`;const candidates=r.candidates||[];return `<div class="result-heading"><span class="badge dark">${esc(A().name)} · 예산 ${shortMoney(state.profile.totalBudget)}</span><h2>${candidates.length?'먼저 검토할 업종 '+candidates.length+'가지':'지금 조건에 맞는 운영안이 없습니다.'}</h2><p>${candidates.length?'예산과 운영 조건에 맞춘 우선순위입니다. 금액은 시장 평균이 아닌 수정 가능한 계획 가정입니다.':'예산·시간 조건을 통과한 후보가 없어 억지로 추천하지 않습니다. 아래 제외 이유를 확인해 주세요.'}</p></div><div class="recommend-grid">${candidates.map((c,i)=>`<article class="card recommend-card"><div class="recommend-top"><span class="rank"><b>0${i+1}</b> 검토 ${i+1}순위</span><button class="save-button" data-save-candidate="${c.id}" aria-label="${esc(c.name)} 저장">＋</button></div><div class="recommend-body"><h3>${esc(c.name)}</h3><div class="recommend-subtitle">${esc(c.conditions.serviceLabel)} · ${esc(c.conditions.operatingFocus)}</div>${list(c.reasons.slice(0,2),'reason-list')}<div class="rec-metrics"><div><label>초기 현금 가정</label><b>${shortMoney(c.budget.plannedCash)}</b></div><div><label>하루 손익분기</label><b>${Math.ceil(c.finance.bepCustomersPerDay)}<small>${c.assumptions.capacityBasis==='orders'?'건':'명'}</small></b></div></div><p class="assumption-note">월세 ${shortMoney(c.assumptions.rent)} · 객단가 ${money(c.assumptions.ticket)} 가정</p><div class="risk-line">확인할 점 · ${esc(c.weaknesses[0])}</div><div class="button-row"><button class="button wide" data-use-candidate="${c.id}">이 업종으로 비용 계산 →</button></div><button class="text-button mini-link" data-candidate-detail="${c.id}">선정 이유 · 지역 근거 · 현장 체크</button></div></article>`).join('')}</div>${r.warnings?.length?`<div class="notice amber">${esc(r.warnings.join(' '))}</div>`:''}<details class="advanced"><summary>제외된 업종과 판단 기준 보기 (${r.excluded?.length||0})</summary>${(r.excluded||[]).map(e=>`<div class="notice"><b>${esc(e.name)}</b><br>${esc((e.blockers||[]).map(b=>b.text).join(' ')||(e.reasons||e.exclusionReasons||[]).join(' ')||e.reason||'입력 조건 미충족')}</div>`).join('')}<p class="chart-note">${esc(r.basis)} · ${esc(r.assumptionNote)}</p></details>`;}
function candidateById(id){return recommendation?.candidates.find(c=>c.id===id);}
function candidateDetails(id){const c=candidateById(id);if(!c)return;const ev=c.competitionEvidence;openDialog(c.name+' · 검토 근거',`<span class="badge">${esc(c.status)}</span><h3>이 조건에서 먼저 살펴보는 이유</h3>${list(c.reasons)}<h3>지역과 경쟁 근거</h3><p>${esc(A().name)} · ${esc([A().residents?.date,A().workers?.date,A().flow?.date].filter(Boolean).filter((v,i,a)=>a.indexOf(v)===i).join(' / ')||'지역 자료 기준일 미확인')}</p>${ev?.rows?.length?`<dl>${ev.rows.map(x=>`<dt>${esc(x.name)} ${x.requiresReview?'<span class="badge">원자료 검토 필요</span>':''}</dt><dd>${x.available===false?'원자료 행 없음':Number.isFinite(x.reportedStoreCount)?nf(x.reportedStoreCount)+'개':'미확인'} · ${esc(ev.period||'기준 분기 미확인')}</dd>`).join('')}</dl><p>공식 분기 집계이며 현재 영업 중인 직접 경쟁점 수는 아닙니다. 누락은 0개가 아니며, 원자료 검토 표시가 있는 행과 점포 수는 추천 점수에 사용하지 않습니다.</p>`:'<p>이 후보에 대응하는 최신 업종별 경쟁 집계는 연결되지 않았습니다.</p>'}<h3>운영 요건과 위험</h3>${list(c.requirements)}${list(c.weaknesses)}<h3>직접 확인할 것</h3>${list(c.fieldChecks)}<h3>초기 현금 가정</h3><dl>${[['보증금',c.budget.deposit],['권리금·양도금',c.budget.transfer],['공사·설비',c.budget.fitout],['개점 부대비',c.budget.openingCosts],['예비 운영자금',c.budget.reserve],['합계',c.budget.plannedCash]].map(([l,v])=>`<dt>${l}</dt><dd>${money(v)}</dd>`).join('')}</dl><p>${esc(c.assumptions.note)}</p><details class="advanced"><summary>우선순위 산식 확인</summary><p>${esc(c.scoreLabel)} ${c.score}점. 성공확률이 아닙니다.</p>${list(c.scoreBreakdown.map(x=>x.criterion+' '+x.points+'점: '+x.reason))}</details><button class="button wide" data-use-candidate="${c.id}">내 조건으로 손익 다시 계산</button>`);}

function renderArea(){const a=A(),d=pop(),ratio=share(a),model=state.population==='flow'?'생활인구':'거주인구',time=a.flow?.timeBands,visible=visibleAreas();return intro('READ THE NEIGHBORHOOD','이 동네에는<br class="mobile-only"> 누가, 언제 올까요?','연령 구성과 시간대, 직장 수요를 함께 살펴보세요.')+regionPicker()+`<div class="scroll-chips">${['20-39','40-59','60+','all'].map(k=>`<button class="chip ${state.age===k?'active':''}" data-age="${k}">${ageLabel(k)}</button>`).join('')}</div><div class="area-layout"><div><section class="card map-card"><div class="section-head"><h2>선택한 동네와 최근 후보</h2>${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(Number.isFinite(a.lat)&&Number.isFinite(a.lng)?a.lat+','+a.lng:(a.province||'')+' '+a.name),'지도 열기','small')}</div><div class="map-canvas" id="map" aria-label="선택 지역 대표 위치"></div><div class="map-legend">${visible.map((b,i)=>`<button data-area="${esc(b.id)}" class="${b.id===a.id?'active':''}"><b>${i+1}</b>${esc(b.short||b.name)}</button>`).join('')}</div><p class="map-caption">대표 좌표이며 상권 경계·가게 앞 유동·매물 건물 위치가 아닙니다. 지도에는 최대 8곳만 표시합니다.</p></section><div class="status-line"><span class="live-dot"></span>${esc(a.flow?.date||a.residents?.date||a.workers?.date||a.sourcePeriod||'인구 통계 미연결')} · 기준 시점의 통계</div></div><div>${stats()}<section class="card"><div class="section-head"><h2>${model}의 연령 구성</h2><div class="layer-switch"><button class="${state.population==='residents'?'active':''}" data-pop="residents">거주</button><button class="${state.population==='flow'?'active':''}" data-pop="flow" ${!a.flow?'disabled':''}>유동</button></div></div><span class="badge">${ratio===null?'미확인':ratio.toFixed(1)+'%'} · ${ageLabel(state.age)}</span><div class="age-bars">${['first','20-39','40-59','60+'].map(k=>{const value=d?.groups?.[k],r=Number.isFinite(value)&&d?.total>0?value/d.total*100:null;return `<div class="age-bar ${state.age===k?'active':''}"><div class="bar-label"><span>${ageLabel(k)}</span><b>${r===null?'미확인':r.toFixed(1)+'%'}</b></div><div class="bar-track"><i style="width:${r===null?0:Math.max(0,Math.min(100,r))}%"></i></div></div>`;}).join('')}</div><p class="chart-note">${esc(d?.note||'이 지역의 해당 인구·연령 자료는 연결되지 않았습니다. 빈 항목은 0명이 아닙니다.')}<br>${String(d?.sourceId||'').startsWith('OA-')?link('https://data.seoul.go.kr/dataList/'+d.sourceId+'/S/1/datasetView.do','원자료'):Number.isFinite(d?.total)?link(d.sourceUrl||C().areaSource,'원자료'):''}</p></section></div></div>${time&&a.flow?.total>0?`<section class="section card"><div class="section-head"><h2>시간 구간별 생활인구 구성</h2><small>${esc(a.flow.date)}<br>구간 합계의 비중</small></div><div class="time-chart">${Object.entries(time).map(([k,v])=>{const r=Number.isFinite(v)?v/a.flow.total*100:null;return `<div class="time-col"><b>${r===null?'미확인':r.toFixed(1)+'%'}</b><div class="time-track"><i style="height:${r===null?0:Math.min(100,r*3)}%"></i></div><span>${esc(k.replace('_','–'))}시</span></div>`;}).join('')}</div><p class="chart-note">구간 길이가 3–6시간으로 다릅니다. 시간당 혼잡도·일평균 방문자·실제 구매 고객 수가 아닙니다.</p></section>`:'<div class="notice amber">이 지역의 시간대별 유동인구는 미연결입니다. 인구 자료가 없는 지역도 공개 점포 목록과 비용 계획은 검토할 수 있습니다.</div>'}<section id="beta-live" class="section"></section><section class="section"><div class="section-head"><h2>최근 후보와 비교</h2><button class="text-button" data-beta="region-search">다른 지역 검색 →</button></div><div class="area-compare">${visible.map(b=>`<button data-area="${esc(b.id)}" class="${b.id===a.id?'active':''}"><strong>${esc(b.name)}</strong><small>${esc(b.localName||b.district||'')} · 거주 ${nf(b.residents?.total)}명</small><b>${share(b)===null?'—':share(b).toFixed(1)+'%'}</b></button>`).join('')}</div><p class="chart-note">${ageLabel(state.age)} ${model} 비중. 지역마다 면적·자료 범위·연도가 다릅니다. 연령은 개별 음식점의 고객 정보가 아닙니다.</p></section><div class="button-row"><button class="button" data-nav="discover">이 동네에서 업종 찾기</button><button class="button secondary" data-nav="rivals">경쟁 확인</button></div>`;}
function fallbackMap(){const areas=visibleAreas().filter(a=>Number.isFinite(a.lat)&&Number.isFinite(a.lng));if(!areas.length)return '<div class="map-unavailable">이 지역의 검증된 대표 좌표가 없습니다.</div>';const minX=Math.min(...areas.map(a=>a.lng)),maxX=Math.max(...areas.map(a=>a.lng)),minY=Math.min(...areas.map(a=>a.lat)),maxY=Math.max(...areas.map(a=>a.lat));const pos=areas.map(a=>({x:38+(a.lng-minX)/(maxX-minX||1)*324,y:245-(a.lat-minY)/(maxY-minY||1)*185}));const points=pos.map(p=>({...p}));for(let loop=0;loop<12;loop++)for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){const dx=points[j].x-points[i].x,dy=points[j].y-points[i].y,dist=Math.hypot(dx,dy);if(dist<32){const amt=(32-dist)/2+1;const nx=dist?dx/dist:1,ny=dist?dy/dist:0;points[i].x-=nx*amt;points[i].y-=ny*amt;points[j].x+=nx*amt;points[j].y+=ny*amt;}}return `<span class="map-note">지도 배경 미지원 환경 · 좌표 위치 비교도</span><svg viewBox="0 0 400 285" role="group" aria-label="${esc(C().city)} 후보 위치"><defs><pattern id="grid" width="32" height="32" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#c5d5b7"/></pattern></defs><rect width="400" height="285" fill="#edf3e6"/><rect width="400" height="285" fill="url(#grid)"/><text x="200" y="160" text-anchor="middle" fill="#dfe9d5" font-size="39" font-weight="700" letter-spacing="9">${state.country==='KR'?'KOREA':'JAPAN'}</text><text x="375" y="35" fill="#839b71" font-size="10">N ↑</text>${areas.map((a,i)=>`<g role="button" tabindex="0" data-area="${esc(a.id)}" aria-label="${esc(a.name)} 선택"><line x1="${pos[i].x}" y1="${pos[i].y}" x2="${points[i].x}" y2="${points[i].y}" stroke="#90ad76"/><circle cx="${pos[i].x}" cy="${pos[i].y}" r="3" fill="#9bb887"/><circle cx="${points[i].x}" cy="${points[i].y}" r="12" fill="${a.id===state.area?'#215b40':'#fff'}" stroke="#a4bd91"/><text x="${points[i].x}" y="${points[i].y+4}" text-anchor="middle" font-size="11" font-weight="600" fill="${a.id===state.area?'#fff':'#6a8757'}">${i+1}</text></g>`).join('')}</svg>`;}
async function initializeMap(){if(!$('#map'))return;const mapAreas=visibleAreas().filter(a=>Number.isFinite(a.lat)&&Number.isFinite(a.lng));if(!mapAreas.length){$('#map').innerHTML=fallbackMap();return;}const gen=++mapGeneration;$('#map').innerHTML=fallbackMap();try{const m=await import('https://unpkg.com/maplibre-gl@6.15.0/dist/maplibre-gl.mjs');if(gen!==mapGeneration||!$('#map'))return;if(!m.supported())return;$('#map').innerHTML='';map=new m.Map({container:'map',style:'https://tiles.openfreemap.org/styles/positron',center:[mapAreas[0].lng,mapAreas[0].lat],zoom:C().zoom,attributionControl:true});const bounds=new m.LngLatBounds();mapAreas.forEach((a,i)=>{bounds.extend([a.lng,a.lat]);const el=document.createElement('button');el.className='map-marker'+(a.id===state.area?' selected':'');el.textContent=i+1;el.setAttribute('aria-label',a.name+' 선택');el.addEventListener('click',()=>chooseArea(a.id));new m.Marker({element:el}).setLngLat([a.lng,a.lat]).addTo(map);});map.fitBounds(bounds,{padding:45,maxZoom:15,duration:0});map.addControl(new m.NavigationControl({showCompass:false}),'top-right');}catch{if(gen===mapGeneration&&$('#map')){$('#map').innerHTML=fallbackMap();map=null;}}}

const financeFields={rent:['월 임대료',''],management:['월 관리비','미확인 금액은 직접 입력'],ticket:['객단가','시장 평균이 아닌 계획 금액'],payroll:['월 인건비','대표자 보수·사업주 부담금 포함'],seats:['좌석 수',''],turns:['하루 최대 회전 수','운영 가능 시간과 주방능력 기준'],ordersPerDay:['하루 주문 처리 상한','좌석 대신 조리·포장 처리 능력'],variableRate:['변동비율 (%)','식재료·포장·결제·배달수수료'],days:['월 영업일','1–31일'],occupancy:['가동률 (%)','처리 상한 대비 이용 가정'],otherFixed:['기타 월 고정비','공과금·보험·이자 등'],depreciation:['월 감가상각','설비·공사비의 회계상 배분'],debtPrincipal:['월 대출 원금 상환','손익과 현금을 구분'],targetProfit:['목표 월 이익','감당 가능한 월세 계산'],deposit:['보증금','월 비용이 아닌 초기 현금'],transfer:['권리금·설비양도금','미확인은 공란'],fitout:['공사·설비비','실제 견적으로 수정'],openingCosts:['개점 부대비','중개·보증·허가 등'],reserve:['예비 운영자금','개점 후 버틸 현금']};
function inputField(k){const [label,note]=financeFields[k],rate=['variableRate','occupancy'].includes(k),v=state.finance[k];return `<label for="f-${k}">${label}<input id="f-${k}" data-finance="${k}" type="number" inputmode="decimal" min="0" ${k==='days'?'max="31" step="1"':k==='seats'?'step="1"':'step="any"'} value="${Number.isFinite(v)?(rate?+(v*100).toFixed(4):v):''}" placeholder="금액 확인 필요"><span class="field-note">${note||'선택 통화: '+C().currencyName}</span></label>`;}
function propertyWorkflow(){return `<nav class="property-workflow" aria-label="매물 검토 순서"><button class="button secondary" data-action="property-discovery"><b>1</b><span>원문 후보 탐색 · 직접 입력</span></button><button class="button secondary" data-action="finance-input"><b>2</b><span>비용 · 운영 가정 입력</span></button><button class="button secondary" data-action="finance-result"><b>3</b><span>손익 · 초기 자금 결과</span></button><button class="button secondary" data-action="compare-properties"><b>4</b><span>매물 임차비 비교</span></button></nav><p class="chart-note">원문에서 후보 확인 → 매물 비용 적용 → 미확인 비용과 운영 가정 입력 → 결과·임차비 비교. 자동 매물 검색·공실 확인 서비스가 아닙니다.</p>`;}
function tokyoVacancySearch(){return state.country==='JP'?`<section class="card vacancy-search" aria-label="도쿄 빈 점포 외부 검색"><h3>⌖ 도쿄 빈 점포를 지도에서 찾기</h3><p>도쿄도가 안내하는 TOKYO 상점가 빈 점포 나비입니다.</p><div class="button-row"><a class="button" href="https://akitenpo.tokyo/search/" target="_blank" rel="noopener noreferrer">도쿄 빈 점포 검색 ↗</a><button class="button secondary" data-beta="add-property">찾은 후보 직접 등록</button></div><p class="chart-note">새 창에서 市区郡 → 新宿区, 업종 → 焼肉・韓国料理를 선택해 보세요. 월세·면적·역 조건과 지도도 사용할 수 있습니다. 일본어 사이트이며 JavaScript가 필요합니다.</p><p class="chart-note">외부 검색 링크입니다. Atlas 자동 수집·실시간 연동이 아니며, 신주쿠 검색 결과 수와 현재 공실은 미확인입니다. 원문 사진과 계약 조건은 공급자에게 확인하고, 확인한 링크·비용만 직접 등록하세요.</p></section>`:'';}
function openPropertyDiscovery(){const records=allProperties().filter(p=>safeUrl(p.source));openDialog('1 · 원문 후보 확인과 직접 입력',`${tokyoVacancySearch()}<p>아래는 저장된 매물의 원문입니다. 현재 공실·가격·주소·음식점 운영 가능 여부는 원문과 공급자에게 확인하세요. 새 후보는 직접 찾은 원문 링크와 확인한 비용으로 등록하세요.</p><button class="button wide" data-beta="add-property">＋ 후보 매물 직접 입력</button><div class="discovery-records">${records.map(p=>`<article class="card"><h3>${esc(p.title)}</h3>${link(p.source,'원문에서 후보 확인 ↗')}<p class="chart-note">기록 기준일: ${esc(p.sourceDate||'미확인')} · ${esc(p.taxNote||'세금 포함 여부 미확인')}</p></article>`).join('')||'<p class="notice">원문 링크가 저장된 후보가 없습니다. 확인한 매물을 직접 등록해 주세요.</p>'}</div>`);}
function renderPlaces(){return intro('SPACE & ECONOMICS','이 자리에서<br class="mobile-only"> 얼마를 팔아야 할까요?','공개 매물의 비용을 넣고 손익분기와 필요한 초기 자금을 계산하세요.')+propertyWorkflow()+tokyoVacancySearch()+`<div class="section-head"><h2>${esc(A().name)} 검토 · ${esc(C().label)} 공개 참고/직접 등록 매물 ${allProperties().length}건</h2><div class="button-row property-top-actions"><button class="button secondary small" data-action="compare-properties">매물 나란히 비교</button><button class="button secondary small" data-beta="add-property">＋ 직접 등록</button></div></div><div class="notice">아래는 국가별 보유 목록이며 선택 동네로 조회한 매물이 아닙니다. 주소를 확인해 비용만 적용하세요. 자동 매물 공급은 계약 전이며 공개 매물은 출처 확인일의 기록입니다.</div><div class="property-grid">${allProperties().map(p=>`<article class="card property-card"><div class="property-strip"><span>${esc(p.localTitle)} · ${esc(p.floor)}</span><b>${esc(p.condition)}</b></div><div class="property-body"><h3>${esc(p.title)}</h3><div class="property-price"><small>월세</small>${shortMoney(p.rent)}</div><div class="property-meta"><span class="badge outline">${esc(p.areaDisplay)}</span><span class="badge outline">보증금 ${shortMoney(p.deposit)}</span></div><p class="property-detail">${esc(p.note)}</p><div class="property-location-link">${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent((p.localTitle||p.title)),'⌖ 주소를 지도에서 확인')}</div><p class="assumption-note">${esc(p.taxNote)}</p><button class="button soft wide" data-property="${esc(p.id)}">이 매물 비용으로 계산 ↓</button><div class="property-source">${link(p.source,'매물 원문·사진 확인')}<span>${esc(p.sourceDate||'원문 기준일 미확인')}</span></div>${p.manual?`<div class="manual-actions"><span class="badge">직접 등록</span><button class="text-button" data-beta="delete-property" data-id="${esc(p.id)}">삭제</button></div>`:''}</div></article>`).join('')}</div><div class="notice">매물의 현재 공실·계약 가능 여부는 확인 전입니다. 공개 정보의 비용만 수록했으며, 분석 상권 안에 있는지와 음식점 운영 조건은 매물별 확인이 필요합니다.</div><section class="section" id="finance-section"><div class="finance-head"><div class="eyebrow">MY BUSINESS SCENARIO · ${C().currency}</div><h2>${esc(state.concept?.name||'내 운영 계획')} 손익 계산</h2><p>실제 매출 예측이 아닌 입력 가정의 산술 계산입니다.</p><button class="button soft small" style="margin-top:13px" data-action="finance-result">계산 결과 바로 보기 ↓</button></div><div class="finance-panel"><div id="property-applied">${appliedPropertyNotice()}</div><div class="finance-layout"><div class="finance-inputs"><div class="form-grid">${['rent','management','ticket','payroll'].map(inputField).join('')}<div class="full"><label class="form-label" for="capacity-basis">판매량을 계산할 기준</label><select id="capacity-basis"><option value="seats" ${state.finance.capacityBasis!=='orders'?'selected':''}>좌석 · 회전 수</option><option value="orders" ${state.finance.capacityBasis==='orders'?'selected':''}>포장 · 주문 처리량</option></select></div>${(state.finance.capacityBasis==='orders'?['ordersPerDay','occupancy']:['seats','turns']).map(inputField).join('')}</div><details class="advanced" open><summary>영업·원가·목표 이익</summary><div class="form-grid">${['variableRate','days',...(state.finance.capacityBasis==='orders'?[]:['occupancy']),'otherFixed','depreciation','debtPrincipal','targetProfit'].map(inputField).join('')}</div></details><details class="advanced" open><summary>초기 자금 · 보증금부터 예비자금까지</summary><div class="form-grid">${['deposit','transfer','fitout','openingCosts','reserve'].map(inputField).join('')}</div></details><p class="chart-note">원화와 엔화 입력은 별도로 저장합니다. 같은 계산 안에서는 세금 포함 기준을 맞추고, 미확인 항목은 견적 또는 명시적인 가정을 입력하세요.</p></div><div><div id="finance-output" aria-live="polite"></div><button id="save-scenario" class="button wide" style="margin-top:15px" data-action="save-finance">이 운영안 저장하기</button></div></div></div></section>`;}
function appliedPropertyNotice(){const p=appliedProperty();if(!p)return `<div class="notice no-margin" style="margin-bottom:20px!important">${state.property?'적용했던 매물 기록을 확인할 수 없습니다. 입력한 비용은 남아 있으며 원문·견적을 다시 확인해 주세요.':(state.concept?'선택한 업종의':'초기')+' 계획 가정입니다. 실제 월세·견적과 운영 조건으로 수정해 주세요.'}</div>`;const labels={rent:'월세',management:'관리비',deposit:'보증금',transfer:'권리금·양도금'},sourced=[],missing=[],edited=[];for(const [k,label]of Object.entries(labels)){if(!Number.isFinite(state.finance[k]))missing.push(label);else if(Number.isFinite(p[k])&&state.finance[k]===p[k])sourced.push(label);else edited.push(label);}return `<div class="notice amber"><b>${esc(p.title)}</b> 비용 적용 · 기록 기준일 ${esc(p.sourceDate||'미확인')} · ${esc(p.taxNote||'세금 포함 여부 확인 필요')}<br>${sourced.length?'매물 기록값 적용: '+esc(sourced.join(' · '))+'<br>':''}${missing.length?'미확인·입력 필요: '+esc(missing.join(' · '))+'<br>':''}${edited.length?'직접 입력·수정한 값: '+esc(edited.join(' · '))+'<br>':''}인건비·객단가·공사비·예비자금 등은 기존 계획 가정을 유지합니다. 상권과 매물 위치·음식점 운영 조건은 별도 확인입니다.${Number.isFinite(p.additionalMonthly)&&p.additionalMonthly>0?' 별도 지원비 월 '+money(p.additionalMonthly)+'는 기타 고정비와 별도로 추가 계산합니다. 중복 입력하지 마세요.':''}</div>`;}
// Visual summaries use the same validated arithmetic as the detailed result.
function financeVisuals(p,calc){
 const colors=['#28634c','#6d9c76','#b8ca91','#d5ac64','#7999ab'];
 const costs=[['보증금',p.deposit],['권리·양도금',p.transfer],['공사·설비',p.fitout],['개점 비용',p.openingCosts],['예비자금',p.reserve]];
 const total=calc.initialCash;
 const allocation=Number.isFinite(total)&&total>0?`<div class="atlas-stacked" role="img" aria-label="초기자금 항목별 비중">${costs.map(([label,n],i)=>`<span style="flex:${n/total};background:${colors[i]}" title="${esc(label)} ${money(n)}"></span>`).join('')}</div><div class="atlas-chart-key">${costs.map(([label,n],i)=>`<div><i style="background:${colors[i]}"></i><span>${esc(label)}</span><b>${shortMoney(n)}</b></div>`).join('')}</div>`:'<p class="chart-note">배정한 초기 자금이 0입니다.</p>';
 const scale=Math.max(calc.revenue,calc.bepRevenue,1);
 const compare=(label,n,color)=>`<div class="atlas-compare-row"><div><span>${label}</span><b>${shortMoney(n)}</b></div><div class="atlas-compare-track"><i style="width:${Math.max(0,Math.min(100,n/scale*100))}%;background:${color}"></i></div></div>`;
 return `<section class="atlas-visual-summary" aria-label="손익과 초기자금 시각 요약"><div class="atlas-chart-heading"><span>월 매출과 손익분기</span><span class="badge ${calc.operatingProfit<0?'amber':''}">${calc.operatingProfit<0?'손익분기 미달':'손익분기 이상'}</span></div>${compare('입력 가정의 매출',calc.revenue,'#28634c')}${compare('손익분기 매출',calc.bepRevenue,'#d5ac64')}<p class="chart-note">입력한 운영 조건의 계산이며 실제 매출 예측이 아닙니다.</p><div class="atlas-chart-heading"><span>초기자금 배분</span><b>${shortMoney(total)}</b></div>${allocation}</section>`;
}
function calculateFinance(){const p={...state.finance},errors=[];for(const [k]of Object.entries(financeFields)){if((p.capacityBasis==='orders'&&['seats','turns'].includes(k))||(p.capacityBasis!=='orders'&&k==='ordersPerDay'))continue;if(!Number.isFinite(p[k])||p[k]<0)errors.push(financeFields[k][0]+' 항목을 확인해 주세요.');}if(!Number.isInteger(p.days)||p.days<1||p.days>31)errors.push('월 영업일은 1–31의 정수로 입력해 주세요.');if(p.capacityBasis==='orders'&&!(p.ordersPerDay>0))errors.push('하루 주문 처리 상한은 0보다 커야 합니다.');if(p.capacityBasis!=='orders'&&(!Number.isInteger(p.seats)||p.seats<1))errors.push('좌석 수는 1 이상의 정수여야 합니다.');const extra=appliedProperty()?.additionalMonthly??0;const accounting={...p,otherFixed:p.otherFixed===null?null:p.otherFixed+extra};const calc=AtlasDomain.calculate(p.capacityBasis==='orders'?{...accounting,seats:1,turns:p.ordersPerDay}:accounting);if(errors.length){calc.valid=false;calc.errors=[...new Set([...calc.errors,...errors])];}const cashKeys=['deposit','transfer','fitout','openingCosts','reserve'],cashKnown=cashKeys.every(k=>Number.isFinite(p[k])&&p[k]>=0);calc.initialCash=cashKnown?cashKeys.reduce((sum,k)=>sum+p[k],0):null;calc.budgetRemaining=Number.isFinite(state.profile.totalBudget)&&Number.isFinite(calc.initialCash)?state.profile.totalBudget-calc.initialCash:null;if(cashKnown&&!Number.isFinite(calc.initialCash)){calc.valid=false;calc.initialCash=null;calc.errors.push('초기 현금 합계가 계산 가능한 범위를 초과했습니다.');}financeResult=calc;persist('finance-'+state.country,state.finance);const applied=$('#property-applied');if(applied)applied.innerHTML=appliedPropertyNotice();const out=$('#finance-output');if(!out)return;$('#save-scenario').disabled=!calc.valid;if(!calc.valid){out.innerHTML=`<div class="error-box"><b>확인할 입력이 있습니다.</b>${list(calc.errors)}미확인 금액을 0원으로 자동 처리하지 않습니다.</div>`;return;}const unit=p.capacityBasis==='orders'?'건':'명';out.innerHTML=`<div class="finance-result"><h3>손익분기에 필요한 하루 판매량</h3><div class="bep-value">${Math.ceil(calc.bepCustomersPerDay)}<small>${unit} / 영업일</small></div><p>객단가 ${money(p.ticket)} · 월 ${p.days}일 · 변동비 ${(p.variableRate*100).toFixed(1)}% 가정<br>손익분기 월매출 ${money(calc.bepRevenue)}</p>${financeVisuals(p,calc)}${[['입력한 판매량 가정',calc.customersPerDay.toFixed(1)+unit+' / 일'],['가정에 따른 월매출',money(calc.revenue)],['가정에 따른 월 영업이익',money(calc.operatingProfit),calc.operatingProfit<0],['원금 상환 후 월 현금',money(calc.cashAfterDebt),calc.cashAfterDebt<0],['목표 이익을 남길 월세 상한',money(calc.maxAffordableRent),calc.maxAffordableRent<0]].map(([l,v,neg])=>`<div class="result-row ${neg?'negative':''}"><span>${l}</span><b>${v}</b></div>`).join('')}<div class="cash-block">초기 필요 현금 · 보증금+양도금+공사·개점비+예비자금<b>${money(calc.initialCash)}</b>${calc.budgetRemaining===null?'업종 찾기에서 예산을 입력하면 자금 여유도 비교합니다.':'입력 예산 대비 '+(calc.budgetRemaining>=0?'남는 자금 '+money(calc.budgetRemaining):'부족한 자금 '+money(-calc.budgetRemaining))}</div>${calc.maxAffordableRent<0?'<div class="notice amber">이 가정에서는 월세가 0이어도 목표 월 이익에 미달합니다. 판매량·객단가·비용을 다시 검토해 주세요.</div>':''}${calc.budgetRemaining!==null&&calc.budgetRemaining<0?'<div class="notice red">초기 자금이 예산을 초과합니다. 이 상태를 예산 내 출점안으로 보지 마세요.</div>':''}<p class="chart-note">매출은 ${p.capacityBasis==='orders'?'주문 처리 상한×가동률':'좌석×회전 수×가동률'}로 계산합니다. 수요 예측이 아닙니다. 월 현금은 영업이익+감가상각−대출 원금이며 세금·추가 설비투자·운전자본 변동은 별도입니다.</p></div>`;}
function useCandidate(id){const c=candidateById(id);if(!c)return;state.finance={...defaults[state.country],...c.assumptions};state.concept={id:c.id,name:c.name};state.property=null;state.propertyRecord=null;persist('property-record-'+state.country,null);persist('finance-'+state.country,state.finance);persist('concept-'+state.country,state.concept);persist('property-'+state.country,null);$('#detail-dialog').close();navigate('places');$('#finance-section').scrollIntoView({behavior:'smooth',block:'start'});toast(c.name+'의 계획 가정을 적용했습니다.');}
function applyProperty(id){const p=allProperties().find(x=>x.id===id);if(!p)return;state.property=id;state.propertyRecord={...p};persist('property-record-'+state.country,state.propertyRecord);for(const k of ['rent','management','deposit','transfer'])state.finance[k]=p[k]??null;persist('property-'+state.country,id);persist('finance-'+state.country,state.finance);render();$('#finance-section').scrollIntoView({behavior:'smooth',block:'start'});toast('매물 비용을 적용했습니다. 미확인 항목을 확인해 주세요.');}

function allRivals(){return [...(state.country==='KR'?RIVALS.rivals.filter(r=>r.areaId===state.area):[]),...storage.get('rivals-'+state.country,[]).filter(r=>r.areaId===state.area)];}
function rivalMatches(r){if(state.category==='all')return true;const s=(r.category||'')+' '+(r.name||'');return state.category==='cafe'?/카페|커피|디저트|베이커리/.test(s):state.category==='pub'?/주점|주류|바|이자카야/.test(s):!/카페|커피|디저트|베이커리/.test(s);}
function renderRivals(){const r=allRivals().filter(rivalMatches),q=(state.country==='KR'?(A().province||'')+' '+A().name:(A().province||'東京都')+' '+(A().localName||A().name))+' '+({all:'맛집',cafe:'카페',meal:'식당',pub:'주점'}[state.category]);const query=state.country==='KR'?'https://map.naver.com/p/search/'+encodeURIComponent(q):'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(q);const com=ca(),inds=com?.industries.filter(i=>state.category==='all'||(state.category==='cafe'?['cafe','bakery'].includes(i.key):state.category==='pub'?i.key==='pub':!['cafe','bakery','pub'].includes(i.key)))||[];return intro('KNOW YOUR ALTERNATIVES','손님이 고를 다른 가게도<br class="mobile-only"> 함께 살펴보세요.','같은 시간·가격대·식사 목적의 경쟁점을 확인하세요.')+regionPicker()+`<div class="notice">${ageLabel(state.age)} 비중은 <b>지역 인구의 구성</b>입니다. 아래 개별 점포의 실제 구매 고객 연령은 확인되지 않았습니다.</div><section id="beta-shops" class="section"></section><div class="section-head"><h2>저장된 조사 후보 ${r.length}곳</h2><button class="text-button" data-action="add-rival">＋ 직접 추가</button></div><div class="scroll-chips">${[['all','전체'],['meal','식사'],['cafe','카페·디저트'],['pub','주점']].map(([k,l])=>`<button class="chip ${state.category===k?'active':''}" data-category="${k}">${l}</button>`).join('')}</div><div class="rival-grid">${r.map(x=>`<article class="card rival-card"><div class="rival-title"><h3>${esc(x.name)}</h3><span class="badge">${esc(x.category)}</span></div><p class="address">${esc(x.address||'주소 직접 확인')}</p><p class="rival-price">${x.price?.amount?money(x.price.amount)+' · '+esc(x.price.item):'메뉴 가격 직접 확인'}</p><div class="observation-chips">${(x.observationWindows||[]).slice(0,2).map(t=>`<span>${esc(t.dayType)} ${esc(t.from)}–${esc(t.to)}</span>`).join('')}<span>실제 고객 연령 미확인</span></div><p>${esc(x.notes?.[0]||'가격·메뉴·대기·회전율을 현장에서 기록해 보세요.')}</p><div class="property-source">${link(x.sourceUrl,'점포 출처')}<span>${esc(x.verifiedOn||'직접 기록')}</span></div>${x.manual?`<div class="manual-actions"><button class="text-button" data-edit-rival="${esc(x.id)}">기록 수정</button><button class="text-button" data-remove-rival="${esc(x.id)}">삭제</button></div>`:''}</article>`).join('')||'<div class="empty-state"><h3>이 조건의 점포 목록은 아직 없습니다.</h3><p>공식 목록·지도에서 확인한 후보를 직접 기록해 두세요.</p></div>'}</div><p class="chart-note">${state.country==='KR'?'브랜드·관광기관의 공식 주소로 확인한 일부 후보입니다. 상권 경계 안 여부·현재 영업·동일 가격대는 미검증이며, 경쟁점 전수 목록이 아닙니다.':'일본 개별 경쟁점 목록은 아직 미연결입니다. 외부 지도와 직접 기록을 사용해 주세요.'}</p><div class="button-row">${link(query,'지도에서 더 찾아보기','button secondary')}<button class="button secondary" data-action="add-rival">내 조사 기록 추가</button></div>${com?`<section class="section"><div class="section-head"><h2>업종별 경쟁 규모 참고</h2><small>2026년 2분기<br>공식 분기 집계</small></div><div class="area-compare">${inds.map(i=>`<button data-industry="${i.code}"><strong>${esc(i.name)}</strong>${i.recommendation_eligible===false||i.quality_flags?.length?'<span class="badge">원자료 검토 필요</span>':''}<small>${i.available?'개업 '+nf(i.openings)+' · 폐업 '+nf(i.closures)+' · '+(Number.isFinite(i.reported_stores_per_ha)?i.reported_stores_per_ha.toFixed(2):'미확인')+'개/ha':'이 분기 자료 행 없음'}</small><b>${i.available?nf(i.reported_store_count)+'개':'미확인'}</b></button>`).join('')}</div><p class="chart-note">공식 분기 집계와 현재 개별 점포의 영업 상태는 다릅니다. 개·폐업 수를 빼서 현재 영업점 수를 산출하지 않습니다. 밀도는 상권 면적으로 나눈 값이며 수요나 점포 면적을 보정한 경쟁 강도가 아닙니다. ${link(COMPETITION.source?.url,'집계 출처')}</p></section>`:''}<section class="section card"><div class="section-head"><h2>현장에 가면 확인할 것</h2><span class="field-check-progress" id="check-progress"></span></div>${checklist()}<p class="chart-note">체크는 연결·동기화 상태에 따라 저장됩니다. 실제로 확인한 항목에만 표시해 주세요.</p></section>`;}
function checklist(){const values=storage.get('checks-'+state.country+'-'+state.area,{});return `<div class="checklist">${checks.map(([k,title,note])=>`<label><input type="checkbox" data-check="${k}" ${values[k]?'checked':''}><span>${title}<small>${note}</small></span></label>`).join('')}</div>`;}
function updateCheckProgress(){const el=$('#check-progress');if(el)el.textContent=Object.values(storage.get('checks-'+state.country+'-'+state.area,{})).filter(Boolean).length+' / '+checks.length;}
function addRival(id=null){const recordCountry=state.country,recordArea={id:state.area,name:A().name},recordCurrency=C().currency;const existing=id?storage.get('rivals-'+recordCountry,[]).find(r=>r.id===id):null;openDialog('경쟁점 조사 기록',`<p>${esc(recordArea.name)}에서 직접 확인한 점포를 기록합니다. 로그인·저장소 연결 상태에 따라 계정에 동기화됩니다.</p><form id="rival-form" class="stack-form"><label>가게 이름<input name="name" required maxlength="100" placeholder="방문한 가게 이름"></label><label>업종<select name="category"><option>식사·한식</option><option>식사·면·덮밥</option><option>카페·디저트</option><option>주점</option><option>기타</option></select></label><label>주소<input name="address" maxlength="200" placeholder="확인한 주소"></label><label>대표 메뉴 가격 (${recordCurrency})<input name="price" type="number" min="0" inputmode="decimal" placeholder="미확인이면 비워두세요"></label><label>출처 URL<input name="url" type="url" placeholder="https://…"></label><label>현장 메모<textarea name="notes" rows="3" maxlength="2000" placeholder="관찰 날짜·시간, 메뉴, 대기, 좌석과 회전"></textarea></label><p class="chart-note">고객 연령은 미확인으로 기록됩니다. 지역 연령이나 외모로 추정하지 않습니다.</p><button class="button wide" type="submit">조사 기록 저장</button></form>`);if(existing){const f=$('#rival-form');for(const [key,val]of Object.entries({name:existing.name,category:existing.category,address:existing.address,price:existing.price?.amount??'',url:existing.sourceUrl,notes:existing.notes?.[0]||''}))f.elements.namedItem(key).value=val??'';}$('#rival-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),url=String(f.get('url')||'');if(url&&!safeUrl(url)){toast('http 또는 https 출처 주소를 입력해 주세요.');return;}const name=String(f.get('name')).trim();if(!name){toast('가게 이름을 입력해 주세요.');return;}const raw=f.get('price'),price=raw===''?null:Number(raw);if(price!==null&&(!Number.isFinite(price)||price<0)){toast('가격을 확인해 주세요.');return;}const rec={id:existing?.id||'manual-'+Date.now(),areaId:recordArea.id,areaName:recordArea.name,name,category:f.get('category'),address:f.get('address'),sourceUrl:url,verifiedOn:new Date().toISOString().slice(0,10),price:price!==null?{amount:price,item:'직접 기록한 메뉴',currency:recordCurrency}:null,notes:[String(f.get('notes')||'')],actualCustomerAge:'unknown',manual:true};const old=storage.get('rivals-'+recordCountry,[]).filter(r=>r.id!==rec.id);old.unshift(rec);if(!persist('rivals-'+recordCountry,old))return;$('#detail-dialog').close();render();toast('조사 기록을 저장했습니다.');};}

function savedItems(){return storage.get('saved',[]);}
function saveCandidate(id){const c=candidateById(id);if(!c)return;const snap={id:'plan-'+Date.now(),country:state.country,areaId:state.area,areaName:A().name,areaRecord:A(),name:c.name,conceptId:c.id,finance:{...defaults[state.country],...c.assumptions},metrics:c.finance,initialCash:c.budget.plannedCash,budget:state.profile.totalBudget,profile:{...state.profile},property:null,createdAt:new Date().toISOString(),sourceDate:DATA.checkedOn};const old=savedItems();old.unshift(snap);if(persist('saved',old))toast('내 검토에 저장했습니다.');}
function saveFinance(){if(!financeResult?.valid)return;const snap={id:'plan-'+Date.now(),country:state.country,areaId:state.area,areaName:A().name,areaRecord:A(),name:state.concept?.name||'직접 입력 운영안',conceptId:state.concept?.id||null,finance:{...state.finance},metrics:{...financeResult},initialCash:financeResult.initialCash,budget:state.profile.totalBudget,profile:{...state.profile},property:state.property,propertyRecord:appliedProperty(),createdAt:new Date().toISOString(),sourceDate:DATA.checkedOn};const old=savedItems();old.unshift(snap);if(persist('saved',old))toast('운영안을 저장했습니다. 내 검토에서 비교할 수 있습니다.');}
function renderSaved(){const saved=savedItems(),items=saved.filter(x=>x.country===state.country);return intro('YOUR SHORTLIST','내 가게 후보를<br class="mobile-only"> 차근차근 좁혀보세요.','저장한 운영안의 초기 자금·손익분기·월세를 비교하세요.')+`<div class="section-head"><h2>${C().label} 저장한 운영안</h2><span class="saved-count">${items.length}개</span></div>${items.length?`<div class="saved-grid">${items.map(x=>`<article class="card saved-item"><div class="heading-row"><span class="badge">${esc(x.areaName)}</span><button class="text-button" data-delete-plan="${esc(x.id)}">삭제</button></div><h3>${esc(x.name)}</h3><div class="saved-meta"><span>초기 ${shortMoney(x.initialCash)}</span><span>월세 ${shortMoney(x.finance.rent)}</span><span>손익분기 ${Math.ceil(x.metrics.bepCustomersPerDay)}${x.finance.capacityBasis==='orders'?'건':'명'}/일</span></div><p class="chart-note">${x.property?'공개 매물 비용 적용 · 상권 경계 일치 미확인':'계획 가정 · 실제 견적 아님'}<br>저장 ${esc(x.createdAt.slice(0,10))} · 원자료 확인 ${esc(x.sourceDate)}</p><button class="button soft wide" style="margin-top:14px" data-load-plan="${esc(x.id)}">불러와서 수정</button></article>`).join('')}</div>${items.length>1?`<div class="section-head section"><h2>한눈에 비교</h2><small>금액 ${C().currency}</small></div><div class="saved-compare"><table><thead><tr><th>지역 / 운영안</th><th>초기 현금</th><th>하루 손익분기</th><th>월 이익 가정</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.areaName)}<br><b>${esc(x.name)}</b></td><td>${money(x.initialCash)}</td><td>${Math.ceil(x.metrics.bepCustomersPerDay)}${x.finance.capacityBasis==='orders'?'건':'명'}</td><td>${money(x.metrics.operatingProfit)}</td></tr>`).join('')}</tbody></table></div>`:''}<div class="button-row"><button class="button secondary" data-action="export">검토 기록 파일로 내보내기 ↓</button></div>`:`<div class="empty-state"><span class="empty-symbol">♡</span><h3>비교하고 싶은 운영안을 저장해 보세요.</h3><p>추천 카드의 ＋ 또는 손익 계산의 저장 버튼으로<br>후보를 모을 수 있습니다.</p><button class="button" style="margin-top:18px" data-nav="discover">업종 찾으러 가기</button></div>`}<div class="install-tip"><b>휴대폰 홈 화면에 두고 사용하세요.</b><br>Safari의 공유 메뉴 또는 Chrome의 메뉴에서 ‘홈 화면에 추가’를 선택할 수 있습니다. 제공 여부는 브라우저에 따라 다릅니다.</div><div class="notice">로그인한 계정의 저장소가 연결되면 기기 사이에서 기록을 동기화합니다. 기기 저장·오프라인 대기·충돌 여부는 연결 설정에서 확인하세요. 원화·엔화는 환산 없이 각각 비교합니다.</div>`;}
async function loadPlan(id){const s=savedItems().find(x=>x.id===id);if(!s)return;state.country=s.country;loadCountry();if(validAreaSnapshot(s.areaRecord,s.country)){const area=normalizeArea(s.areaRecord),i=C().areas.findIndex(x=>x.id===s.areaId);if(i<0)C().areas.push(area);else if(C().areas[i].isRestoring)C().areas[i]=area;}if(!C().areas.some(x=>x.id===s.areaId&&!x.isRestoring)){const found=await window.AtlasBeta?.findRegion(s.areaId,s.areaName,s.country);if(!found){toast('저장된 지역 자료를 불러오지 못했습니다. 연결 후 다시 시도해 주세요.');return;}const i=C().areas.findIndex(x=>x.id===s.areaId);if(i<0)C().areas.push(normalizeArea(found));else C().areas[i]=normalizeArea(found);}state.area=s.areaId;state.restoreAreaId=null;state.finance={...s.finance};state.profile={...s.profile};state.concept={id:s.conceptId,name:s.name};state.property=s.property;state.propertyRecord=s.propertyRecord||null;for(const [k,v]of [['area',state.area],['area-snapshot',A()],['finance',state.finance],['profile',state.profile],['concept',state.concept],['property',state.property],['property-record',state.propertyRecord]])persist(k+'-'+state.country,v);persist('country',state.country);calculateRecommendations();navigate('places');$('#finance-section').scrollIntoView({behavior:'smooth',block:'start'});window.AtlasBeta?.loadCompetition();}
function exportRecords(){const payload={app:'상권 Atlas',version:'beta-2',exportedAt:new Date().toISOString(),note:'입력 가정과 조사 기록이며 매출 예측이 아닙니다. 국가별 통화를 구분하세요.',plans:savedItems(),manualProperties:{KR:storage.get('properties-KR',[]),JP:storage.get('properties-JP',[])},manualRivals:{KR:storage.get('rivals-KR',[]),JP:storage.get('rivals-JP',[])},checklists:Object.fromEntries(Object.entries(DATA.countries).map(([country,c])=>[country,c.areas.map(a=>({areaId:a.id,areaName:a.name,checks:storage.get('checks-'+country+'-'+a.id,{})}))]))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='atlas-my-plans-'+new Date().toISOString().slice(0,10)+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('검토 기록 파일을 내보냈습니다.');}
function openDialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;}
function showSources(){window.AtlasBeta?.showSources();}
function render(){if(map){map.remove();map=null;}mapGeneration++;renderNav();const renderers={opening:()=>window.AtlasOpeningUI.render(),discover:renderDiscover,area:renderArea,places:renderPlaces,rivals:renderRivals,saved:renderSaved};$('#main').innerHTML=renderers[state.view]();if(state.view==='area')initializeMap();if(state.view==='places')calculateFinance();if(state.view==='rivals')updateCheckProgress();window.AtlasBeta?.afterRender();if(state.view==='opening')window.AtlasOpeningUI?.afterRender();}

document.addEventListener('click',e=>{const t=e.target.closest('[data-nav],[data-action],[data-profile-key],[data-age],[data-pop],[data-area],[data-property],[data-use-candidate],[data-save-candidate],[data-candidate-detail],[data-category],[data-industry],[data-delete-plan],[data-load-plan],[data-edit-rival],[data-remove-rival]');if(!t)return;if(t.dataset.nav){$('#detail-dialog').close();navigate(t.dataset.nav);}else if(t.dataset.profileKey){state.profile[t.dataset.profileKey]=t.dataset.profileValue;persist('profile-'+state.country,state.profile);updateProfileSummary();$$(`[data-profile-key="${t.dataset.profileKey}"]`).forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',String(b===t));});recommendation=null;$('#recommend-results').innerHTML='<div class="notice">조건이 바뀌었습니다. ‘이 조건으로 업종 찾기’를 눌러 다시 계산해 주세요.</div>';}else if(t.dataset.area)chooseArea(t.dataset.area);else if(t.dataset.age){state.age=t.dataset.age;render();}else if(t.dataset.pop){state.population=t.dataset.pop;render();}else if(t.dataset.editRival)addRival(t.dataset.editRival);else if(t.dataset.removeRival){const k='rivals-'+state.country,old=storage.get(k,[]);if(!persist(k,old.filter(r=>r.id!==t.dataset.removeRival)))return;render();openDialog('조사 기록을 삭제했습니다','<p>직접 추가한 조사 기록을 지웠습니다.</p><button class="button wide" id="undo-rival">되돌리기</button>');$('#undo-rival').onclick=()=>{if(!persist(k,old))return;$('#detail-dialog').close();render();};}else if(t.dataset.category){state.category=t.dataset.category;render();}else if(t.dataset.property)applyProperty(t.dataset.property);else if(t.dataset.useCandidate)useCandidate(t.dataset.useCandidate);else if(t.dataset.saveCandidate)saveCandidate(t.dataset.saveCandidate);else if(t.dataset.candidateDetail)candidateDetails(t.dataset.candidateDetail);else if(t.dataset.loadPlan)loadPlan(t.dataset.loadPlan);else if(t.dataset.deletePlan){const old=savedItems(),removed=old.find(x=>x.id===t.dataset.deletePlan);if(!persist('saved',old.filter(x=>x.id!==t.dataset.deletePlan)))return;render();openDialog('운영안을 삭제했습니다',`<p>${esc(removed?.name)}을 목록에서 지웠습니다.</p><button class="button wide" id="undo-delete">되돌리기</button>`);$('#undo-delete').onclick=()=>{if(!persist('saved',old))return;$('#detail-dialog').close();render();};}else if(t.dataset.industry){const i=ca()?.industries.find(x=>x.code===t.dataset.industry);if(i)openDialog(i.name+' · 점포 집계',`<dl><dt>기준 분기</dt><dd>2026년 2분기</dd><dt>집계 점포</dt><dd>${nf(i.reported_store_count)}개</dd><dt>일반 / 가맹</dt><dd>${nf(i.general_store_count)} / ${nf(i.franchise_count)}개</dd><dt>개업 / 폐업</dt><dd>${nf(i.openings)} / ${nf(i.closures)}개</dd><dt>상권 면적</dt><dd>${nf(ca().area_m2)}㎡</dd></dl><p>공식 분기 집계입니다. 현재 영업점 수를 보장하지 않습니다. 가맹점은 전체에 이미 포함되며, 폐업 비율을 내 가게의 실패 확률로 해석하지 않습니다.</p>${i.recommendation_eligible===false||i.quality_flags?.length?'<div class="notice amber">이 행은 원자료 검토가 필요합니다. 개·폐업 수와 집계 점포 수의 일관성을 확인하기 전 현재 영업점 수를 산출하거나 추천 근거로 사용하지 않습니다.</div>':''}${link(COMPETITION.source?.url,'공식 원자료')}`);}else{switch(t.dataset.action){case'sources':showSources();break;case'region-scope':window.AtlasBeta?.openSearch();break;case'add-rival':addRival();break;case'save-finance':saveFinance();break;case'compare-properties':window.AtlasPropertyCompare?.open({properties:allProperties(),country:state.country,currency:C().currency,esc,money,openDialog});break;case'export':exportRecords();break;case'property-discovery':openPropertyDiscovery();break;case'finance-input':$('#finance-section').scrollIntoView({behavior:'smooth',block:'start'});$('#f-rent')?.focus({preventScroll:true});break;case'finance-result':calculateFinance();$('#finance-output').scrollIntoView({behavior:'smooth',block:'start'});break;}}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='country-select'){state.country=t.value;persist('country',state.country);loadCountry();render();window.AtlasBeta?.loadCompetition();window.scrollTo({top:0});}else if(t.id==='area-select')chooseArea(t.value);else if(t.id==='service-select'){state.profile.service=t.value;persist('profile-'+state.country,state.profile);updateProfileSummary();recommendation=null;$('#recommend-results').innerHTML='<div class="notice">조건을 적용하려면 업종 찾기를 눌러 주세요.</div>';}else if(t.id==='capacity-basis'){state.finance.capacityBasis=t.value;render();$('#finance-section').scrollIntoView({block:'start'});}else if(t.dataset.check){const k='checks-'+state.country+'-'+state.area,v=storage.get(k,{});v[t.dataset.check]=t.checked;persist(k,v);updateCheckProgress();}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='budget-input'){const n=Number(t.value);state.profile.totalBudget=t.value&&Number.isFinite(n)?n*10000:null;persist('profile-'+state.country,state.profile);recommendation=null;$('#recommend-results').innerHTML='<div class="notice">입력한 예산으로 업종을 다시 찾아보세요.</div>';}if(t.dataset.finance){let n=t.value===''?null:Number(t.value);if(['variableRate','occupancy'].includes(t.dataset.finance)&&n!==null)n/=100;state.finance[t.dataset.finance]=n;calculateFinance();}});
document.addEventListener('submit',e=>{if(e.target.id!=='fit-form')return;e.preventDefault();const budget=Number($('#budget-input').value)*10000;if(!(budget>0)||!Number.isFinite(budget)){$('#fit-error').textContent='조달 가능한 총 창업 예산을 입력해 주세요.';return;}state.profile.totalBudget=budget;persist('profile-'+state.country,state.profile);calculateRecommendations();$('#recommend-results').innerHTML=renderRecommendations();$('#recommend-results').scrollIntoView({behavior:'smooth',block:'start'});});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('svg [data-area]')){e.preventDefault();chooseArea(e.target.dataset.area);}});
$('#dialog-close').onclick=()=>$('#detail-dialog').close();
window.addEventListener('hashchange',()=>{if(DATA)navigate(location.hash.slice(1));});
async function initialize(){try{const [d,c,r]=await Promise.all([fetch('/data.json').then(x=>{if(!x.ok)throw Error('data');return x.json();}),fetch('/competition.json').then(x=>x.ok?x.json():{areas:[]}).catch(()=>({areas:[]})),fetch('/rivals.json').then(x=>x.ok?x.json():{rivals:[]}).catch(()=>({rivals:[]}))]);DATA=d;for(const country of Object.values(DATA.countries))country.areas=country.areas.map(normalizeArea);COMPETITION=c;RIVALS=r;if(!DATA.countries[state.country])state.country='KR';await import('/beta-ui.js');window.AtlasBeta.init({state:()=>state,data:()=>DATA,competition:()=>COMPETITION,country:C,area:A,storage,esc,nf,money,shortMoney,link,safeUrl,openDialog,toast,render,navigate,allProperties,replacePublicArea,selectArea(area,country){if(country!==state.country){state.country=country;persist('country',country);loadCountry();}const normalized=normalizeArea(area),i=C().areas.findIndex(x=>x.id===normalized.id);if(i<0)C().areas.push(normalized);else C().areas[i]=normalized;chooseArea(normalized.id);},setCompetition(value,id){COMPETITION.areas=(COMPETITION.areas||[]).filter(x=>x.id!==id).concat(value.areas||[]);if(value.source)COMPETITION.source=value.source;if(value.industry_catalog?.length)COMPETITION.industry_catalog=value.industry_catalog;calculateRecommendations();if(['rivals','area'].includes(state.view))render();else if(state.view==='discover'){const out=$('#recommend-results');if(out&&recommendation)out.innerHTML=renderRecommendations();const statsEl=$('.discovery-layout .mini-stats');if(statsEl)statsEl.outerHTML=stats();}}});loadCountry();window.AtlasOpeningUI.init({storage,toast,esc,link,safeUrl,openDialog,country:()=>state.country,area:A,allProperties,render,navigate});navigate(location.hash.slice(1)||(state.country==='KR'?'opening':'discover'),false);window.AtlasBeta.loadCompetition();}catch(error){console.error('Atlas initialization',error?.message);$('#main').innerHTML='<div class="empty-state"><h2>자료를 불러오지 못했습니다.</h2><p>인터넷 연결을 확인한 뒤 화면을 새로 열어 주세요.</p><button class="button" onclick="location.reload()" style="margin-top:18px">다시 불러오기</button></div>';}}

function replacePublicArea(area,country,id){if(state.country!==country||state.area!==id||!validAreaSnapshot(area,country)||String(area.id)!==id)return false;const previous=A(),normalized=normalizeArea(area),i=C().areas.findIndex(a=>a.id===id),changed=JSON.stringify(previous)!==JSON.stringify(normalized);if(i<0)C().areas.push(normalized);else C().areas[i]=normalized;state.restoreAreaId=null;if(state.population==='flow'&&!normalized.flow)state.population='residents';persist('area-snapshot-'+country,normalized);if(!changed)return true;if(recommendation)calculateRecommendations();if(state.view==='area'){render();}else{const picker=$('.region-picker');if(picker)picker.outerHTML=regionPicker();if(state.view==='discover'){const statsEl=$('.discovery-layout .mini-stats');if(statsEl)statsEl.outerHTML=stats();const heading=$('.discovery-layout section .section-head h2');if(heading)heading.textContent=normalized.name+' 먼저 보기';const results=$('#recommend-results');if(results&&recommendation)results.innerHTML=renderRecommendations();}window.AtlasBeta?.publicAreaChanged(previous);}return true;}
function validAreaSnapshot(a,country){return !!a&&typeof a==='object'&&!Array.isArray(a)&&/^[A-Za-z0-9_-]{1,80}$/.test(String(a.id||''))&&typeof a.name==='string'&&a.name.trim().length>0&&(!a.country||a.country===country)&&!a.isRestoring;}
function normalizeArea(a){return {...a,id:String(a.id),residents:{total:null,groups:{},...(a.residents||{})},workers:{total:null,...(a.workers||{})},flow:a.flow&&Number.isFinite(a.flow.total)?{groups:{},...a.flow}:null};}
function visibleAreas(){const a=A(),others=C().areas.filter(x=>x.id!==a.id&&(!a.province||x.province===a.province)&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)).slice(-7).reverse();return [a,...others].slice(0,8);}
function appliedProperty(){return state.propertyRecord?.id===state.property?state.propertyRecord:allProperties().find(x=>x.id===state.property);}
function allProperties(){return [...storage.get('properties-'+state.country,[]),...(C().properties||[])];}
window.addEventListener('atlas-sync-change',e=>{if(e.detail?.accountChanged){location.reload();return;}if(e.detail?.remoteDataChanged&&DATA){const country=storage.get('country',state.country);if(DATA.countries[country])state.country=country;loadCountry();render();window.AtlasBeta?.loadCompetition();toast($('#detail-dialog')?.open?'계정의 새 기록을 반영했습니다. 작성 중인 창은 유지됩니다.':'다른 기기의 최신 기록을 반영했습니다.');}window.AtlasBeta?.updateSync();});

initialize();
